import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kt1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled Conv3d for kernel (KH, KW, 1):
// A thread block computes a TH x TW x TL tile of outputs for OC_TILE
// output channels. The tile's fastest spatial mode runs along the last
// (memory-contiguous) tensor dim L, so both the staged input loads and
// the final output stores are fully coalesced. The corresponding input
// tile (with halo) plus the weights are staged in shared memory for
// full reuse.
//
// Shape-adaptive depth tiling (this optimization): TL/PIX are template
// parameters. For shallow-depth outputs (Lout <= 10, as in this
// workload where the depth is 10) the host launches the TL=10 / PIX=1
// configuration, whose tile matches the depth extent exactly. The
// original fixed TL=16 / PIX=2 tile discarded 6 of every 16
// L-positions at the store stage, i.e. ~37.5% of all issued FMA work
// was wasted. With TL = Lout = 10 no lane is wasted, and because the
// depth rows are contiguous in memory (L == Lout == TL), the staged
// input loads and the output stores both coalesce into full 128-byte
// warp transactions. PIX=1 also halves the live accumulators per
// thread, relieving register pressure. Larger depths keep the generic
// TL=16 / PIX=2 configuration.
constexpr int TH      = 8;
constexpr int TW      = 4;
template <int TL, int PIX, int OC_TILE>
__global__ void __launch_bounds__(TH * TW * (TL / PIX), 3) conv3d_kt1_kernel(
    const float* __restrict__ Xp,
    const float* __restrict__ Wp,
    const float* __restrict__ Bp,
    float* __restrict__ Yp,
    int N, int C, int H, int W, int L,
    int OC, int KH, int KW,
    int stride, int pad, int dil,
    int Hout, int Wout, int Lout,
    int sh, int sw, int sl)
{
  constexpr int TLR     = TL / PIX;      // threads spanning the L tile
  constexpr int THREADS = TH * TW * TLR;
  extern __shared__ float smem[];
  float* sX = smem;                              // C * sh * sw * sl
  const size_t xPad = ((size_t)C * sh * sw * sl + 3) & ~(size_t)3;  // 16B align
  float* sW = smem + xPad;                       // C * KH * KW * OC_TILE (oc fastest)
  const int tid = threadIdx.x;
  // Block coordinates
  const int lTiles = (Lout + TL - 1) / TL;
  const int z      = blockIdx.z;                 // n * lTiles + lt
  const int n      = z / lTiles;
  const int lt     = z - n * lTiles;
  const int ol0    = lt * TL;
  const int il_base = ol0 * stride - pad;        // input slice base (kernel depth = 1)
  const int hTiles = (Hout + TH - 1) / TH;
  const int ht     = blockIdx.y % hTiles;
  const int ocTile = blockIdx.y / hTiles;
  const int wt     = blockIdx.x;
  const int oh0 = ht * TH;
  const int ow0 = wt * (2 * TW);   // each block covers WPIX*TW = 2*TW outputs along W
  const int ih_base = oh0 * stride - pad;
  const int iw_base = ow0 * stride - pad;
  // Global tensors (CuTe)
  auto mX = make_tensor(make_gmem_ptr(Xp),
      make_shape(N, C, H, W, L),
      make_stride((int64_t)C * H * W * L, (int64_t)H * W * L,
                  (int64_t)W * L, (int64_t)L, Int<1>{}));
  auto mW = make_tensor(make_gmem_ptr(Wp),
      make_shape(OC, C, KH, KW),
      make_stride((int64_t)C * KH * KW, (int64_t)KH * KW, (int64_t)KW, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Yp),
      make_shape(N, OC, Hout, Wout, Lout),
      make_stride((int64_t)OC * Hout * Wout * Lout, (int64_t)Hout * Wout * Lout,
                  (int64_t)Wout * Lout, (int64_t)Lout, Int<1>{}));
  // Shared tensors (CuTe)
  auto sXt = make_tensor(make_smem_ptr(sX),
      make_shape(C, sh, sw, sl),
      make_stride((int64_t)sh * sw * sl, (int64_t)sw * sl, (int64_t)sl, Int<1>{}));
  // Weights staged transposed: output channel is the fastest (contiguous)
  // mode so the register-blocked inner loop can use vectorized loads.
  auto sWt = make_tensor(make_smem_ptr(sW),
      make_shape(C, KH, KW, Int<OC_TILE>{}),
      make_stride((int64_t)KH * KW * OC_TILE, (int64_t)KW * OC_TILE,
                  (int64_t)OC_TILE, Int<1>{}));
  // ---- Stage input tile (all channels, with halo) into shared memory ----
  // ---- Consecutive threads walk the contiguous last dim -> coalesced. ---
  const int xElems = C * sh * sw * sl;
  const int xSlice = sh * sw * sl;
  const int xPlane = sw * sl;
  for (int idx = tid; idx < xElems; idx += THREADS) {
    int c    = idx / xSlice;
    int rem  = idx - c * xSlice;
    int r    = rem / xPlane;
    int rem2 = rem - r * xPlane;
    int col  = rem2 / sl;
    int l    = rem2 - col * sl;
    int ih   = ih_base + r;
    int iw   = iw_base + col;
    int il   = il_base + l;
    float v = 0.0f;
    if (ih >= 0 && ih < H && iw >= 0 && iw < W && il >= 0 && il < L) {
      v = mX(n, c, ih, iw, il);
    }
    sXt(c, r, col, l) = v;
  }
  // ---- Stage weights for this output-channel tile into shared memory ----
  const int wElems = C * KH * KW * OC_TILE;
  for (int idx = tid; idx < wElems; idx += THREADS) {
    int oc   = idx % OC_TILE;
    int rem  = idx / OC_TILE;
    int kw   = rem % KW;
    int rem2 = rem / KW;
    int kh   = rem2 % KH;
    int c    = rem2 / KH;
    int goc  = ocTile * OC_TILE + oc;
    float v = 0.0f;
    if (goc < OC) v = mW(goc, c, kh, kw);
    sWt(c, kh, kw, oc) = v;
  }
  __syncthreads();
  // ---- Compute: each thread computes PIX outputs along the contiguous ----
  // ---- last dim for WPIX=2 W-tile positions (register blocking) and  ----
  // ---- OC_TILE output channels. W blocking doubles reuse of every    ----
  // ---- staged weight vector; out-of-range input positions were       ----
  // ---- zero-filled during staging, so no per-tap bounds checks.      ----
  constexpr int WPIX = 2;  // W register blocking; block covers 2*TW outputs
  const int col_l = tid % TLR;
  const int remT  = tid / TLR;
  const int cw    = remT % TW;
  const int r     = remT / TW;
  const int oh    = oh0 + r;
  int  ow[WPIX];
  int  scw[WPIX];
  int  ol[PIX];
  int  scl[PIX];
  bool v[WPIX][PIX];
  bool anyV = false;
  #pragma unroll
  for (int wp = 0; wp < WPIX; ++wp) {
    ow[wp]  = ow0 + cw + wp * TW;
    scw[wp] = (cw + wp * TW) * stride;
  }
  #pragma unroll
  for (int p = 0; p < PIX; ++p) {
    ol[p]  = ol0 + col_l + p * TLR;
    scl[p] = (col_l + p * TLR) * stride;
    #pragma unroll
    for (int wp = 0; wp < WPIX; ++wp) {
      v[wp][p] = (oh < Hout) && (ow[wp] < Wout) && (ol[p] < Lout);
      anyV = anyV || v[wp][p];
    }
  }
  if (anyV) {
    const int sr = r * stride;
    // Register-tile the output channels: the staged weights are consumed
    // in sequential passes of OC_STEP=4, so the live accumulator array
    // shrinks to WPIX*PIX*4 = 8 floats per thread. Profiling shows this
    // kernel is DRAM-write-bound (dram ~78%) with theoretical occupancy
    // capped at 41.7% by its ~96 registers/thread (~2 CTAs of 320
    // threads per SM). Halving the live accumulators versus OC_STEP=8,
    // together with __launch_bounds__(..., 3) above, lets three CTAs
    // reside per SM (~62.5% occupancy) without spilling the hot
    // accumulators, deepening the memory pipeline so far more output
    // stores are in flight to hide DRAM latency. The staged input tile
    // is simply re-read from shared memory once more (large smem
    // bandwidth headroom) with zero extra global traffic. The
    // '#pragma unroll 1' keeps the passes from being interleaved,
    // which would otherwise keep more accumulator sets live.
    constexpr int OC_STEP = 4;
    #pragma unroll 1
    for (int oct = 0; oct < OC_TILE / OC_STEP; ++oct) {
      const int ocB = oct * OC_STEP;
      float acc[WPIX][PIX][OC_STEP];
      #pragma unroll
      for (int wp = 0; wp < WPIX; ++wp) {
        #pragma unroll
        for (int p = 0; p < PIX; ++p) {
          #pragma unroll
          for (int oc = 0; oc < OC_STEP; ++oc) {
            const int goc = ocTile * OC_TILE + ocB + oc;
            const float bv = (Bp != nullptr && goc < OC) ? Bp[goc] : 0.0f;
            acc[wp][p][oc] = bv;
          }
        }
      }
      if (C == 3 && KH == 3 && KW == 3 && stride == 1 && dil == 1) {
        #pragma unroll
        for (int c = 0; c < 3; ++c) {
          #pragma unroll
          for (int kh = 0; kh < 3; ++kh) {
            const int rr = sr + kh;
            #pragma unroll
            for (int kw = 0; kw < 3; ++kw) {
              float xv[WPIX][PIX];
              #pragma unroll
              for (int wp = 0; wp < WPIX; ++wp) {
                const int cc = scw[wp] + kw;
                #pragma unroll
                for (int p = 0; p < PIX; ++p) xv[wp][p] = sXt(c, rr, cc, scl[p]);
              }
              const float4* w4 =
                  reinterpret_cast<const float4*>(&sWt(c, kh, kw, ocB));
              #pragma unroll
              for (int q = 0; q < OC_STEP / 4; ++q) {
                const float4 wv = w4[q];
                #pragma unroll
                for (int wp = 0; wp < WPIX; ++wp) {
                  #pragma unroll
                  for (int p = 0; p < PIX; ++p) {
                    acc[wp][p][4 * q + 0] += xv[wp][p] * wv.x;
                    acc[wp][p][4 * q + 1] += xv[wp][p] * wv.y;
                    acc[wp][p][4 * q + 2] += xv[wp][p] * wv.z;
                    acc[wp][p][4 * q + 3] += xv[wp][p] * wv.w;
                  }
                }
              }
            }
          }
        }
      } else {
        for (int c = 0; c < C; ++c) {
          for (int kh = 0; kh < KH; ++kh) {
            const int rr = sr + kh * dil;
            #pragma unroll 4
            for (int kw = 0; kw < KW; ++kw) {
              float xv[WPIX][PIX];
              #pragma unroll
              for (int wp = 0; wp < WPIX; ++wp) {
                const int cc = scw[wp] + kw * dil;
                #pragma unroll
                for (int p = 0; p < PIX; ++p) xv[wp][p] = sXt(c, rr, cc, scl[p]);
              }
              const float4* w4 =
                  reinterpret_cast<const float4*>(&sWt(c, kh, kw, ocB));
              #pragma unroll
              for (int q = 0; q < OC_STEP / 4; ++q) {
                const float4 wv = w4[q];
                #pragma unroll
                for (int wp = 0; wp < WPIX; ++wp) {
                  #pragma unroll
                  for (int p = 0; p < PIX; ++p) {
                    acc[wp][p][4 * q + 0] += xv[wp][p] * wv.x;
                    acc[wp][p][4 * q + 1] += xv[wp][p] * wv.y;
                    acc[wp][p][4 * q + 2] += xv[wp][p] * wv.z;
                    acc[wp][p][4 * q + 3] += xv[wp][p] * wv.w;
                  }
                }
              }
            }
          }
        }
      }
      #pragma unroll
      for (int wp = 0; wp < WPIX; ++wp) {
        #pragma unroll
        for (int p = 0; p < PIX; ++p) {
          if (v[wp][p]) {
            #pragma unroll
            for (int oc = 0; oc < OC_STEP; ++oc) {
              const int goc = ocTile * OC_TILE + ocB + oc;
              if (goc < OC) mY(n, goc, oh, ow[wp], ol[p]) = acc[wp][p][oc];
            }
          }
        }
      }
    }
  }
}

torch::Tensor conv3d_kt1_forward(torch::Tensor x,
                                 torch::Tensor w,
                                 c10::optional<torch::Tensor> b,
                                 int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, L]");
  TORCH_CHECK(w.dim() == 5, "w must be [OC, C, KH, KW, 1]");
  TORCH_CHECK(w.size(4) == 1, "kernel size along last dim must be 1");
  TORCH_CHECK(stride > 0 && dilation > 0 && padding >= 0,
              "invalid stride/dilation/padding");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N  = x_c.size(0);
  const int64_t C  = x_c.size(1);
  const int64_t H  = x_c.size(2);
  const int64_t W  = x_c.size(3);
  const int64_t L  = x_c.size(4);
  const int64_t OC = w_c.size(0);
  const int64_t KH = w_c.size(2);
  const int64_t KW = w_c.size(3);
  TORCH_CHECK(w_c.size(1) == C, "w.size(1) must equal in_channels (groups=1)");

  const int64_t Hout = (H + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  const int64_t Wout = (W + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  const int64_t Lout = (L + 2 * padding - 1) / stride + 1;  // kernel depth 1
  TORCH_CHECK(Hout > 0 && Wout > 0 && Lout > 0, "invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout, Lout}, x_c.options());

  const int sh = (int)((TH - 1) * stride + dilation * (KH - 1) + 1);
  const int sw = (int)((2 * TW - 1) * stride + dilation * (KW - 1) + 1);
  const int64_t wTiles  = (Wout + 2 * TW - 1) / (2 * TW);
  const int64_t hTiles  = (Hout + TH - 1) / TH;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  auto launch = [&](auto tlC, auto pixC, auto ocC) {
    constexpr int TL  = decltype(tlC)::value;
    constexpr int PIX = decltype(pixC)::value;
    constexpr int OC_TILE = decltype(ocC)::value;
    const int64_t ocTiles = (OC + OC_TILE - 1) / OC_TILE;
    const int sl = (int)((TL - 1) * stride + 1);  // kernel depth = 1
    const size_t xPad = ((size_t)C * sh * sw * sl + 3) & ~(size_t)3;
    const size_t smem_bytes =
        (xPad + (size_t)OC_TILE * C * KH * KW) * sizeof(float);
    if (smem_bytes > 48 * 1024) {
      cudaFuncSetAttribute(conv3d_kt1_kernel<TL, PIX, OC_TILE>,
                           cudaFuncAttributeMaxDynamicSharedMemorySize,
                           (int)smem_bytes);
    }
    const int64_t lTiles = (Lout + TL - 1) / TL;
    dim3 block(TH * TW * (TL / PIX));
    dim3 grid((unsigned)wTiles,
              (unsigned)(hTiles * ocTiles),
              (unsigned)(N * lTiles));
    conv3d_kt1_kernel<TL, PIX, OC_TILE><<<grid, block, smem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)C, (int)H, (int)W, (int)L,
        (int)OC, (int)KH, (int)KW,
        stride, padding, dilation,
        (int)Hout, (int)Wout, (int)Lout,
        sh, sw, sl);
  };
  // Full-OC-tile optimization (this change): profiling shows the kernel is
  // DRAM-bound (dram ~83%) while the input halo tile is re-staged from
  // global memory once per 16-wide output-channel tile (4x redundant input
  // traffic for OC=64). When OC is a multiple of 64, stage the input tile
  // once and compute all 64 output channels in the same block
  // (OC_TILE=64, consumed in sequential OC_STEP=8 register passes so
  // register pressure and the float4 weight loads are unchanged), cutting
  // input staging traffic ~4x. Other shapes keep the OC_TILE=16 config.
  const bool oc64 = (OC % 64 == 0) &&
                    ((size_t)C * KH * KW * 64 <= (size_t)160 * 1024);
  if (Lout <= 10) {
    if (oc64) {
      launch(Int<10>{}, Int<1>{}, Int<64>{});
  // once and compute all 64 output channels in the same block
  // (OC_TILE=64, consumed in sequential OC_STEP=4 register passes so
    }
  } else {
    if (oc64) {
      launch(Int<16>{}, Int<2>{}, Int<64>{});
    } else {
      launch(Int<16>{}, Int<2>{}, Int<16>{});
    }
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kt1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_kt1_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_kt1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution with kernel (kernel_size, kernel_size, 1),
    implemented with a single cooperative-tiled CuTe CUDA kernel.
    The nn.Conv3d module is kept only as the parameter container so that
    initialization and state_dict match the reference model exactly.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == 1, "ModelNew supports groups == 1 only"
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.conv3d = nn.Conv3d(in_channels, out_channels,
                                (kernel_size, kernel_size, 1),
                                stride=stride, padding=padding,
                                dilation=dilation, groups=groups, bias=bias)
        self._ext = conv3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv3d.bias if self.conv3d.bias is not None else None
        return self._ext.conv3d_kt1_forward(
            x.contiguous(),
            self.conv3d.weight.contiguous(),
            bias,
            self.stride,
            self.padding,
            self.dilation,
        )

